49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "membership_number")
67	    private String membershipNumber;
68	
69	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
70	    private Set<Pet> pets;
71	
72	    public String getAddress() {
73	        return this.address;
74	    }
75	
76	    public void setAddress(String address) {
77	        this.address = address;
78	    }
79	
80	    public String getCity() {
81	        return this.city;
82	    }
83	
84	    public void setCity(String city) {
85	        this.city = city;
86	    }
87	
88	    public String getTelephone() {
89	        return this.telephone;
90	    }
91	
92	    public void setTelephone(String telephone) {
93	        this.telephone = telephone;
94	    }
95	
96	    public String getEmail() {
97	        return this.email;
98	    }
99	
100	    public void setEmail(String email) {
101	        this.email = email;
102	    }
103	
104	    public LocalDate getRegistrationDate() {
105	        return this.registrationDate;
106	    }
107	
108	    public void setRegistrationDate(LocalDate registrationDate) {
109	        this.registrationDate = registrationDate;
110	    }
111	
112	    public String getCustomerCode() {
113	        return this.customerCode;
114	    }
115	
116	    public void setCustomerCode(String customerCode) {
117	        this.customerCode = customerCode;
118	    }
119	
120	    public String getHouseholdId() {
121	        return this.householdId;
122	    }
123	
124	    public void setHouseholdId(String householdId) {
125	        this.householdId = householdId;
126	    }
127	
128	    public Integer getNamesakeCount() {
129	        return this.namesakeCount;
130	    }
131	
132	    public void setNamesakeCount(Integer namesakeCount) {
133	        this.namesakeCount = namesakeCount;
134	    }
135	
136	    public String getMembershipNumber() {
137	        return this.membershipNumber;
138	    }
139	
140	    public void setMembershipNumber(String membershipNumber) {
141	        this.membershipNumber = membershipNumber;
142	    }
143	
144	    protected Set<Pet> getPetsInternal() {
145	        if (this.pets == null) {
146	            this.pets = new HashSet<>();
147	        }
148	        return this.pets;
149	    }
150	
151	    protected void setPetsInternal(Set<Pet> pets) {
152	        this.pets = pets;
153	    }
154	
155	    public List<Pet> getPets() {
156	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
157	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
158	        return Collections.unmodifiableList(sortedPets);
159	    }
160	
161	    public void setPets(List<Pet> pets) {
162	        this.pets = new HashSet<>(pets);
163	    }
164	
165	    public void addPet(Pet pet) {
166	        getPetsInternal().add(pet);
167	        pet.setOwner(this);
168	    }
169	
170	    /**
171	     * Return the Pet with the given name, or null if none found for this Owner.
172	     *
173	     * @param name to test
174	     * @return true if pet name is already in use
175	     */
176	    public Pet getPet(String name) {
177	        return getPet(name, false);
178	    }
179	
180	    /**
181	     * Return the Pet with the given name, or null if none found for this Owner.
182	     *
183	     * @param name to test
184	     * @return true if pet name is already in use
185	     */
186	    public Pet getPet(String name, boolean ignoreNew) {
187	        name = name.toLowerCase();
188	        for (Pet pet : getPetsInternal()) {
189	            if (!ignoreNew || !pet.isNew()) {
190	                String compName = pet.getName();
191	                compName = compName.toLowerCase();
192	                if (compName.equals(name)) {
193	                    return pet;
194	                }
195	            }
196	        }
197	        return null;
198	    }
199	
200	    public Pet getPet(Integer petId) {
201	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
202	    }
203	
204	    @Override
205	    public String toString() {
206	        return new ToStringCreator(this)
207	
208	            .append("id", this.getId())
209	            .append("new", this.isNew())
210	            .append("lastName", this.getLastName())
211	            .append("firstName", this.getFirstName())
212	            .append("address", this.address)
213	            .append("city", this.city)
214	            .append("telephone", this.telephone)
215	            .append("email", this.email)
216	            .toString();
217	    }
